   132    {
   133      TRACE_SANITIZE (this);
   134      return_trace (rowWidth.sanitize (c) &&
   135                    leftClassTable.sanitize (c, this) &&
   136                    rightClassTable.sanitize (c, this) &&
   137                    array.sanitize (c, this));
   138    }
